#include "rubik.h"

/* Optimal 2x2x2 solver, meet in the middle.
 *
 * rubik_tables.inc (generated by mytests/gen_rubik_tables.py) holds every
 * state within RUBIK_NEAR_DEPTH (5) moves of solved as a sorted table of
 * packed states, and every state at distance 11 as a second sorted table.
 *
 * A depth-first search from the input state to depth 5 looks each visited
 * state up in the near table; a hit at depth d with table depth t is a
 * solution of d + t moves, and the smallest such sum over the whole tree is
 * the exact distance (the optimal path of length D <= 10 has a node at depth
 * max(0, D - 5) whose distance is min(D, 5)). A state that is not found is at
 * distance 11: its table entry gives a first move to a distance-10 state.
 *
 * A state is packed into 32 bits: p[0..5] in 3 bits each (p[6] is implied),
 * then o[0..6] in 2 bits each. No multiply or divide is needed anywhere.
 */

#include "rubik_tables.inc"

enum { CUBIES = 7, MOVES = 9, MAX_MOVES = 11 };

struct cube {
    uint8_t p[CUBIES];
    uint8_t o[CUBIES];
};

static const uint8_t face_of[MOVES] = {0, 0, 0, 1, 1, 1, 2, 2, 2};
static const uint8_t mod3[5] = {0, 1, 2, 0, 1};
static const char move_name[MOVES][3] = {"R",  "R2", "R'", "B", "B2",
                                         "B'", "D",  "D2", "D'"};

static struct cube turn(const struct cube *c, int m)
{
    struct cube n;
    const uint8_t *src = rubik_move_src[m];
    const uint8_t *tw = rubik_move_twist[m];
    for (int i = 0; i < CUBIES; i++) {
        n.p[i] = c->p[src[i]];
        n.o[i] = mod3[c->o[src[i]] + tw[i]];
    }
    return n;
}

static uint32_t pack(const struct cube *c)
{
    uint32_t code = 0;
    for (int i = 0; i < CUBIES - 1; i++)
        code = (code << 3) | c->p[i];
    for (int i = 0; i < CUBIES; i++)
        code = (code << 2) | c->o[i];
    return code;
}

/* Index of key in the sorted table, or -1. */
static int lookup(const uint32_t *keys, int count, uint32_t key)
{
    int lo = 0, hi = count - 1;
    while (lo <= hi) {
        int mid = lo + ((hi - lo) >> 1);
        uint32_t k = keys[mid];
        if (k == key)
            return mid;
        if (k < key)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return -1;
}

struct search {
    uint8_t stack[RUBIK_NEAR_DEPTH]; /* moves applied so far */
    uint8_t best_path[RUBIK_NEAR_DEPTH];
    int best_len;      /* d + t of the best hit, or MAX_MOVES + 1 */
    int best_depth;    /* d of the best hit */
    uint32_t best_key; /* the hit state */
};

static void dfs(struct search *s, const struct cube *c, int depth, int last)
{
    uint32_t key = pack(c);
    int idx = lookup(rubik_near_key, RUBIK_NEAR_COUNT, key);
    if (idx >= 0) {
        int total = depth + (rubik_near_aux[idx] >> 4);
        if (total < s->best_len) {
            s->best_len = total;
            s->best_depth = depth;
            s->best_key = key;
            for (int i = 0; i < depth; i++)
                s->best_path[i] = s->stack[i];
        }
    }
    if (depth == RUBIK_NEAR_DEPTH)
        return;
    for (int m = 0; m < MOVES; m++) {
        if (last >= 0 && face_of[m] == face_of[last])
            continue;
        struct cube n = turn(c, m);
        s->stack[depth] = (uint8_t) m;
        dfs(s, &n, depth + 1, m);
    }
}

/* Parse and validate; returns 0 on success. */
static int parse(const char *state, struct cube *c)
{
    unsigned seen = 0, osum = 0;
    for (int i = 0; i < CUBIES; i++) {
        char ch = state[i];
        if (ch < '1' || ch > '7')
            return -1;
        unsigned bit = 1u << (ch - '1');
        if (seen & bit)
            return -1;
        seen |= bit;
        c->p[i] = (uint8_t) (ch - '1');
    }
    for (int i = 0; i < CUBIES; i++) {
        char ch = state[CUBIES + i];
        if (ch < '1' || ch > '3')
            return -1;
        c->o[i] = (uint8_t) (ch - '1');
        osum += (unsigned) (ch - '1');
    }
    if (state[RUBIK_STATE_LEN] != '\0')
        return -1;
    /* osum <= 14; a multiple of 3 is 0, 3, 6, 9 or 12. */
    while (osum >= 3)
        osum -= 3;
    return osum == 0 ? 0 : -1;
}

int rubik_solve(const char *state, char *out, size_t cap)
{
    struct cube c;
    if (parse(state, &c) != 0)
        return -1;

    uint8_t moves[MAX_MOVES];
    int n = 0;

    /* Distance 11: one table move first. */
    int far = lookup(rubik_far_key, RUBIK_FAR_COUNT, pack(&c));
    if (far >= 0) {
        int m = rubik_far_move[far];
        moves[n++] = (uint8_t) m;
        c = turn(&c, m);
    }

    struct search s;
    s.best_len = MAX_MOVES + 1;
    s.best_depth = 0;
    s.best_key = 0;
    dfs(&s, &c, 0, -1);
    if (s.best_len > MAX_MOVES)
        return -1; /* cannot happen for a valid state */

    for (int i = 0; i < s.best_depth; i++)
        moves[n++] = s.best_path[i];

    /* Walk the near table from the hit back to solved. */
    struct cube w = c;
    for (int i = 0; i < s.best_depth; i++)
        w = turn(&w, s.best_path[i]);
    uint32_t key = s.best_key;
    for (;;) {
        int idx = lookup(rubik_near_key, RUBIK_NEAR_COUNT, key);
        if (idx < 0)
            break; /* cannot happen: the chain stays inside the table */
        uint8_t aux = rubik_near_aux[idx];
        if ((aux >> 4) == 0)
            break;
        int m = aux & 15;
        moves[n++] = (uint8_t) m;
        w = turn(&w, m);
        key = pack(&w);
    }

    /* Text length: names plus single spaces, plus the NUL. */
    size_t len = 0;
    for (int i = 0; i < n; i++)
        len += (move_name[moves[i]][1] ? 2 : 1) + (i ? 1 : 0);
    if (len + 1 > cap) {
        if (cap >= 1)
            out[0] = '\0';
        return -2;
    }
    size_t pos = 0;
    for (int i = 0; i < n; i++) {
        if (i)
            out[pos++] = ' ';
        out[pos++] = move_name[moves[i]][0];
        if (move_name[moves[i]][1])
            out[pos++] = move_name[moves[i]][1];
    }
    out[pos] = '\0';
    return n;
}
